INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist eine CLI immer langsamer als eine GUI bei der Ausführung von Befehlen?', 2, '[{"text": "Nein", "correct": true, "because": "CLI hat oft weniger Overhead"}, {"text": "Ja", "correct": false, "because": "GUI benötigt mehr Ressourcen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature macht eine CLI für Admins besonders nützlich?', 3, '[{"text": "Skriptfähigkeit", "correct": true, "because": "Automatisierung spart Zeit"}, {"text": "Interaktive Menüs", "correct": false, "because": "Eher GUI-Feature"}, {"text": "Grafische Ausgabe", "correct": false, "because": "CLI ist textbasiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine CLI gegenüber einer GUI?', 5, '[{"text": "Geringerer Ressourcenverbrauch", "correct": true, "because": "Kein grafischer Overhead"}, {"text": "Schnelle Befehlseingabe", "correct": true, "because": "Direkt ohne Maus"}, {"text": "Augenschonender Modus", "correct": false, "because": "Kein Fokus auf Design"}, {"text": "Hohe Auflösung", "correct": false, "because": "Textbasiert, nicht visuell"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eine CLI ist ohne Terminal nutzlos. b) GUI ersetzt CLI komplett.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "CLI braucht Terminal, GUI ergänzt nur"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Entwicklung einer CLI-Anwendung?', 4, '[{"text": "Befehlssyntax", "correct": false, "because": "Kern der Bedienung"}, {"text": "Fehlermeldungen", "correct": false, "because": "Wichtig für Nutzer"}, {"text": "Farbige Ausgabe", "correct": true, "because": "Nice-to-have, nicht essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine CLI auch ohne Shell laufen kann?', 2, '[{"text": "Ja", "correct": true, "because": "Direkt über OS möglich"}, {"text": "Nein", "correct": false, "because": "Shell oft Standard, aber nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Befehl nutze ich in einer CLI, um Netzwerkverbindungen zu prüfen?', 3, '[{"text": "ping", "correct": true, "because": "Testet Erreichbarkeit"}, {"text": "dir", "correct": false, "because": "Listet nur Dateien"}, {"text": "echo", "correct": false, "because": "Gibt nur Text aus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Features machen eine CLI mächtig?', 5, '[{"text": "Pipes", "correct": true, "because": "Verknüpfen von Befehlen"}, {"text": "Skripte", "correct": true, "because": "Automatisieren Aufgaben"}, {"text": "Grafische Buttons", "correct": false, "because": "GUI-Feature"}, {"text": "Hohe Auflösung", "correct": false, "because": "Nicht CLI-relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) CLI ist nur für Nerds. b) GUI ist immer benutzerfreundlicher. Stimmt das?', 3, '[{"text": "Beides falsch", "correct": true, "because": "CLI ist für Profis, GUI nicht immer besser"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Beide sind falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine CLI-Anwendung?', 4, '[{"text": "Befehlszeilenparser", "correct": false, "because": "Verarbeitet Eingaben"}, {"text": "Hilfefunktion", "correct": false, "because": "Unterstützt Nutzer"}, {"text": "Mausunterstützung", "correct": true, "because": "CLI ist tastaturbasiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist eine CLI immer plattformabhängig?', 2, '[{"text": "Nein", "correct": true, "because": "Portable Tools wie Bash existieren"}, {"text": "Ja", "correct": false, "because": "Abhängigkeit überwindbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Tools nutze ich in einer CLI für Netzwerkdiagnose?', 4, '[{"text": "tracert", "correct": true, "because": "Zeigt Routing-Pfad"}, {"text": "netstat", "correct": true, "because": "Listet Verbindungen"}, {"text": "notepad", "correct": false, "because": "Nur Texteditor"}, {"text": "calc", "correct": false, "because": "Rechner, kein Netzwerktool"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass eine CLI keine Fehler meldet. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Fehlerausgabe ist Standard"}, {"text": "Ja", "correct": false, "because": "Fehlermeldungen sind essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature priorisiere ich bei einer CLI für Admins?', 3, '[{"text": "Autovervollständigung", "correct": true, "because": "Spart Zeit und Fehler"}, {"text": "Hohe Schriftgröße", "correct": false, "because": "Sekundär"}, {"text": "Grafische Icons", "correct": false, "because": "Nicht CLI-relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) CLI-Befehle sind oft kürzer als GUI-Klicks. b) GUI ist immer intuitiver.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Intuition abhängig von Nutzer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche CLI-Befehle helfen bei der Prozessverwaltung?', 5, '[{"text": "tasklist", "correct": true, "because": "Zeigt laufende Prozesse"}, {"text": "kill", "correct": true, "because": "Beendet Prozesse"}, {"text": "mkdir", "correct": false, "because": "Nur Verzeichnisse"}, {"text": "cd", "correct": false, "because": "Nur Navigation"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer CLI unwichtig?', 3, '[{"text": "Klarheit der Befehle", "correct": false, "because": "Kern der Nutzbarkeit"}, {"text": "Fehlercodes", "correct": false, "because": "Diagnosehilfe"}, {"text": "3D-Animationen", "correct": true, "because": "Textbasiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal mit der CLI? Kann sie komplexe Workflows steuern?', 3, '[{"text": "Ja", "correct": true, "because": "Skripte und Pipes ermöglichen das"}, {"text": "Nein", "correct": false, "because": "Nicht auf einfache Befehle beschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine CLI auch GUI-Elemente integrieren kann?', 2, '[{"text": "Nein", "correct": true, "because": "Rein textbasiert"}, {"text": "Ja", "correct": false, "because": "Hybrid wäre keine reine CLI"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen CLI-Befehl wähle ich für eine schnelle Systemübersicht?', 4, '[{"text": "systeminfo", "correct": true, "because": "Zeigt detaillierte Infos"}, {"text": "cls", "correct": false, "because": "Nur Bildschirm leeren"}, {"text": "ver", "correct": false, "because": "Nur Versionsnummer"}]');
